            return (
              <g
                key={node.id}
                className={classes.join(' ').trim()}
                transform={`translate(${position.x} ${position.y})`}
                data-node-id={node.id}
                data-node-kind={node.kind}
                onFocus={event => {
                  // Pointer focus must not move the click/drag target before the gesture finishes.
                  if (event.target.matches(':focus-visible') && !event.target.hasAttribute('data-restoring-focus')) ensureVisible(node.id)
                }}
              >
                <g
                  className="node-body"
                  role="button"
                  tabIndex={0}
                  aria-label={label}
                  aria-pressed={isFolder ? isSelected : undefined}
                  {...pointerHandlers}
                  onKeyDown={onNodeKeyDown(node)}
                >
                  <title>{label}</title>
                  <circle className="focus-ring" r={radius + 6} />
                  {node.kind === 'source' && <circle className="shape" r={radius} />}
                  {node.kind === 'location' && <rect className="shape" x={-24} y={-17} width={48} height={34} rx={9} />}
                  {node.kind === 'directory' && <path className="shape" d="M -20 -15 h 12 l 4 4 h 24 v 26 h -40 z" />}
                  {node.kind === 'file' && (
                    <>
                      <path className="shape" d="M -10 -14 h 14 l 6 6 v 22 h -20 z" />
                      <path className="shape-detail" d="M 4 -14 v 6 h 6 M -6 0 h 12 M -6 6 h 12" />
                    </>
                  )}
                  {node.kind === 'source' && showLabel && (
                    <text className="label" textAnchor="middle" y={5} aria-hidden="true">{node.name}</text>
                  )}
                </g>
                {node.kind !== 'source' && (showLabel || (isExpanded && isEmpty) || unavailable) && (
                  <g className="node-label" aria-hidden="true" {...pointerHandlers}>
                    {showLabel && (
                      <text className="label" textAnchor="middle" y={radius + 16}>
                        {lines.map((line, i) => <tspan key={i} x="0" dy={i === 0 ? 0 : 13}>{line}</tspan>)}
                      </text>
                    )}
                    {isExpanded && isEmpty && (
                      <text className="empty-tag" textAnchor="middle" y={radius + 16 + (showLabel ? lines.length : 0) * 13}>empty</text>
                    )}
                    {unavailable && (
                      <text className="unavailable-tag" textAnchor="middle" y={radius + 16 + (showLabel ? lines.length : 0) * 13}>unavailable</text>
                    )}
                  </g>
                )}
                {isFolder && (
                  <g
                    className="node-toggle"
                    role="button"
                    tabIndex={0}
                    aria-expanded={isExpanded}
                    aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
                    transform={`translate(${radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onToggleExpand(node)}
                    onKeyDown={activate(() => onToggleExpand(node))}
                  >
                    <circle r={9} />
                    <path d={isExpanded ? 'M -4 0 h 8' : 'M -4 0 h 8 M 0 -4 v 8'} />
                  </g>
                )}
                {pinned && (
                  <g
                    className="node-pin"
                    role="button"
                    tabIndex={0}
                    aria-label={`Unpin ${node.name}`}
                    transform={`translate(${-radius * 0.85} ${-radius * 0.85})`}
                    onPointerDown={stop}
                    onClick={() => onTogglePin(node)}
                    onKeyDown={activate(() => onTogglePin(node))}
                  >
                    <circle r={8} />
                    <path d="M -3 -3 h 6 l -1 4 h -4 z M 0 1 v 5" />
                  </g>
                )}
              </g>
            )
          })}
        </g>
      </g>
    </svg>
  )
})
import { useState, type MouseEvent } from 'react'
import { breadcrumbsFor, breadcrumbsForFile, folderToPathname, type FileRef, type FolderRef, type TreeIndex } from './model.ts'

type Props = {
  selected: FolderRef | null
  /** When set, the trail leads to the file's folder and ends with the filename as a non-navigating item. */
  file?: FileRef | null
  /** Supplies location labels; while the listing is loading the location id is shown instead. */
  index: TreeIndex | null
  onNavigate: (ref: FolderRef | null) => void
}

/** Home / source / location / folder / current fits; deeper trails collapse the middle. */
const MAX_VISIBLE = 5

/** Home / Source / Location / folder … trail. Long trails collapse the middle behind an expandable “…” control. */
export function Breadcrumbs({ selected, file = null, index, onNavigate }: Props) {
  const [showAll, setShowAll] = useState(false)
  const crumbs = file ? breadcrumbsForFile(file, index) : breadcrumbsFor(selected, index)
  const collapsed = !showAll && crumbs.length > MAX_VISIBLE
  const hidden = collapsed ? crumbs.slice(1, crumbs.length - 2) : []
  const visible = collapsed ? [crumbs[0], ...crumbs.slice(crumbs.length - 2)] : crumbs

  const follow = (ref: FolderRef | null) => (event: MouseEvent<HTMLAnchorElement>) => {
    event.preventDefault()
    onNavigate(ref)
  }

  return (
    <nav className="breadcrumbs" aria-label="Breadcrumb">
      <ol>
        {visible.map((crumb, position) => {
          const isCurrent = position === visible.length - 1
          return (
            <li key={crumb.id}>
              {position === 1 && hidden.length > 0 && (
                <>
                  <button
                    type="button"
                    className="breadcrumb-ellipsis"
                    aria-expanded={false}
                    aria-label={`Show ${hidden.length} hidden breadcrumb ${hidden.length === 1 ? 'level' : 'levels'}`}
                    onClick={() => setShowAll(true)}
                  >
                    …
                  </button>
                  <span className="breadcrumb-separator" aria-hidden="true">/</span>
                </>
              )}
              {crumb.ref === undefined ? (
                <span className="breadcrumb-current" aria-current="page">{crumb.label}</span>
              ) : (
                <a href={folderToPathname(crumb.ref)} aria-current={isCurrent ? 'page' : undefined} onClick={follow(crumb.ref)}>
                  {crumb.label}
                </a>
              )}
              {!isCurrent && <span className="breadcrumb-separator" aria-hidden="true">/</span>}
            </li>
          )
        })}
      </ol>
    </nav>
  )
}
import { useLayoutEffect, useRef, type MutableRefObject } from 'react'
import { childCounts, childrenOf, describeCounts, SOURCES, type GraphNode, type TreeIndex } from './model.ts'

type Props = {
  index: TreeIndex
  expanded: ReadonlySet<string>
  selectedId: string | null
  /** Scroll position survives unmounting (graph mode, document view) through this owner-held store. */
  scrollRef: MutableRefObject<number>
  onSelect: (node: GraphNode) => void
  onOpenFile: (node: GraphNode) => void
  onToggleExpand: (node: GraphNode) => void
}

const ICONS: Record<GraphNode['kind'], string> = { source: '◎', location: '▣', directory: '▰', file: '▤' }
const KIND_TEXT: Record<GraphNode['kind'], string> = { source: 'source', location: 'location', directory: 'folder', file: 'Markdown file' }

/** Accessible replacement for the graph: the same tree, expansion state and selection as nested lists. */
export function Outline({ index, expanded, selectedId, scrollRef, onSelect, onOpenFile, onToggleExpand }: Props) {
  const container = useRef<HTMLElement>(null)
  useLayoutEffect(() => {
    if (container.current) container.current.scrollTop = scrollRef.current
  }, [scrollRef])

  function renderFolder(node: GraphNode) {
    const isExpanded = expanded.has(node.id)
    const counts = childCounts(index, node.id)
    const children = childrenOf(index, node.id)
    const unavailable = node.kind === 'location' && node.location?.status === 'unavailable'
    const summary = unavailable ? `Unavailable: ${node.location?.error ?? 'this location cannot be read.'}` : describeCounts(counts, node.kind)
    return (
      <li key={node.id} className={`outline-item outline-${node.kind}`} data-node-id={node.id}>
        <div className="outline-row">
          <button
            type="button"
            className="outline-toggle"
            aria-expanded={isExpanded}
            aria-label={`${isExpanded ? 'Collapse' : 'Expand'} ${node.name}`}
            onClick={() => onToggleExpand(node)}
          >
            <svg viewBox="0 0 10 10" width="10" height="10" aria-hidden="true">
              <path d={isExpanded ? 'M 1 3 L 5 7 L 9 3' : 'M 3 1 L 7 5 L 3 9'} />
            </svg>
          </button>
          <button
            type="button"
            className="outline-name"
            aria-current={node.id === selectedId ? 'true' : undefined}
            onClick={() => onSelect(node)}
          >
            <span className="outline-icon" aria-hidden="true">{ICONS[node.kind]}</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, {KIND_TEXT[node.kind]}{unavailable ? ', unavailable' : ''}</span>
          </button>
          <span className={unavailable ? 'outline-counts outline-unavailable' : 'outline-counts'}>{summary}</span>
        </div>
        {isExpanded && (
          <ul className="outline-list">
            {unavailable
              ? <li className="outline-empty outline-unavailable">{summary}</li>
              : children.length === 0
                ? <li className="outline-empty">{node.kind === 'source' ? 'No locations are configured for this source.' : 'This folder is empty.'}</li>
                : children.map(child => (child.kind === 'file' ? renderFile(child) : renderFolder(child)))}
          </ul>
        )}
      </li>
    )
  }

  function renderFile(node: GraphNode) {
    return (
      <li key={node.id} className="outline-item outline-file" data-node-id={node.id}>
        <div className="outline-row">
          <button type="button" className="outline-name outline-file-name" onClick={() => onOpenFile(node)}>
            <span className="outline-icon" aria-hidden="true">{ICONS.file}</span>
            <span>{node.name}</span>
            <span className="visually-hidden">, Markdown file</span>
          </button>
        </div>
      </li>
    )
  }

  return (
    <nav
      className="outline"
      aria-label="Directory outline"
      ref={container}
      onScroll={event => { scrollRef.current = event.currentTarget.scrollTop }}
    >
      <ul className="outline-list outline-root">
        {SOURCES.map(source => renderFolder(index.nodes.get(source)!))}
      </ul>
    </nav>
  )
}
/** Wraps a name into short lines, preferring to break after separators. Full names stay in aria-labels. */
export function wrapLabel(name: string, maxChars = 14, maxLines = 3): string[] {
  const lines: string[] = []
  let rest = name
  while (rest.length > 0 && lines.length < maxLines) {
    if (rest.length <= maxChars) { lines.push(rest); rest = ''; break }
    let cut = -1
    for (let i = maxChars; i > 3; i -= 1) {
      if ('-_. '.includes(rest[i - 1])) { cut = i; break }
    }
    if (cut === -1) cut = maxChars
    lines.push(rest.slice(0, cut).trimEnd())
    rest = rest.slice(cut).trimStart()
  }
  if (rest.length > 0) lines[lines.length - 1] = `${lines[lines.length - 1].slice(0, maxChars - 1)}…`
  return lines
}

content.content:
.app {
