  font-size: 0.875rem;
  color: var(--text);
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 6px 12px;
  min-width: 40px;
  min-height: 36px;
  cursor: pointer;
}
.button:hover:not(:disabled) { background: var(--surface-alt); }
.button:disabled { opacity: 0.5; cursor: default; }
.button[aria-pressed='true'] { background: var(--accent); color: var(--accent-contrast); border-color: var(--accent); }
.button:focus-visible, .breadcrumbs a:focus-visible, .breadcrumb-ellipsis:focus-visible, .missing a:focus-visible,
